import Hero from "@/components/home/Hero";
import MarqueeTicker from "@/components/home/MarqueeTicker";
import ProductList from "@/components/home/ProductList";
import FadeIn from "@/components/ui/FadeIn";
import type { Product } from "@/types/product";

const API_BASE_URL = process.env.LARAVEL_API_URL ?? "http://127.0.0.1:8001/api";

async function getProducts(): Promise<Product[]> {
  try {
    const response = await fetch(`${API_BASE_URL}/products`, {
      cache: "no-store",
      headers: { Accept: "application/json" },
    });

    if (!response.ok) throw new Error("Không tải được sản phẩm.");

    return await response.json();
  } catch {
    return [];
  }
}

export default async function Home() {
  const productsData = await getProducts();
  const bestSellers = productsData.filter((product) => product.isBestSeller || product.is_best_seller).slice(0, 4);
  const women = productsData.filter((product) => product.category === "Nước hoa nữ").slice(0, 4);
  const men = productsData.filter((product) => product.category === "Nước hoa nam").slice(0, 4);
  const unisex = productsData.filter((product) => product.category === "Unisex").slice(0, 4);

  return (
    <div className="min-h-screen bg-[#070607] text-[#f7efe1]">
      <div className="px-3 pt-3 sm:px-5 sm:pt-5 lg:px-8 lg:pt-8">
        <Hero />
        <MarqueeTicker />
      </div>

      <section className="mx-auto grid max-w-[1500px] gap-8 border-x border-[#d6bd7a]/18 bg-[#0b0908] px-5 py-12 sm:px-8 lg:grid-cols-3 lg:px-14">
        {[
          ["01", "Rare compositions", "Những nhóm hương được chọn theo cảm giác boutique, ít ồn ào và rất có gu."],
          ["02", "Evening character", "Tông amber, oud, iris và santal tạo nên chất sang trầm, hợp tiệc tối."],
          ["03", "Modern ritual", "Giao diện mua sắm gọn, để sản phẩm và giá trị cảm xúc đứng trước."],
        ].map(([num, title, body]) => (
          <div key={num} className="border-t border-[#d6bd7a]/30 pt-5">
            <span className="text-xs font-semibold uppercase tracking-[0.28em] text-[#d6bd7a]">{num}</span>
            <h2 className="mt-3 font-serif text-3xl text-[#f7efe1]">{title}</h2>
            <p className="mt-3 text-sm leading-7 text-[#cfc4ad]/75">{body}</p>
          </div>
        ))}
      </section>

      <div className="mx-auto max-w-[1500px] space-y-20 border-x border-[#d6bd7a]/18 bg-[linear-gradient(180deg,#0b0908_0%,#120e0c_48%,#070607_100%)] px-5 py-16 sm:px-8 lg:px-14 lg:py-20">
        <FadeIn direction="up" delay={0.1}>
          <ProductList id="ban-chay" eyebrow="Signature edit" title="Mùi hương bán chạy" products={bestSellers} />
        </FadeIn>
        <FadeIn direction="up" delay={0.2}>
          <ProductList id="nuoc-hoa-nu" eyebrow="Soft floral" title="Nước hoa nữ" products={women} viewMoreLink="/category/nuoc-hoa-nu" />
        </FadeIn>
        <FadeIn direction="up" delay={0.3}>
          <ProductList id="nuoc-hoa-nam" eyebrow="Clean woods" title="Nước hoa nam" products={men} viewMoreLink="/category/nuoc-hoa-nam" />
        </FadeIn>
        <FadeIn direction="up" delay={0.4}>
          <ProductList id="unisex" eyebrow="Shared scents" title="Nước hoa unisex" products={unisex} viewMoreLink="/category/unisex" />
        </FadeIn>
      </div>
    </div>
  );
}
